(53411, 'Jeremiah 11:22', 'Jeremiah', 11, 22, 'نو مالِک خُدائ ربُ الافواج د دوئ په حقله فرمائى، زۀ به هغوئ له سزا ورکړم. د هغوئ ځوانان به په جنګ کښې ووژلے شى، او د هغوئ زامن او لوڼه به د قحط په وجه مړۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah11_verse_22.mp3', '', 1761754199, 1761754199),
(53412, 'Jeremiah 11:23', 'Jeremiah', 11, 23, 'د هغوئ نه به يو هم بچ پاتې نۀ شى ځکه چې زۀ به د عنتوت په خلقو افت رانازل کړم. کله چې د هغوئ د سزا وخت راورسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah11_verse_23.mp3', '', 1761754199, 1761754199),
(53413, 'Deuteronomy 33:1', 'Deuteronomy', 33, 1, 'دا هغه برکتونه دي چې د خدای پیغمبر موسی د خپل مرګ څخه مخکې د اسراییلو قوم ته ورکړل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_1.mp3', '', 1761754199, 1761754199),
(53414, 'Deuteronomy 33:2', 'Deuteronomy', 33, 2, 'څښتن راغی د سینا له غره نه هغه راپورته شو ادوم باندې د لمر په شان او وځلېده د فاران له غره نه په خپل قوم باندې د هغه سره وې لس زره فرښتې او په ښي لاس کې یې د اور لمبه وه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_2.mp3', '', 1761754199, 1761754199),
(53415, 'Deuteronomy 33:3', 'Deuteronomy', 33, 3, 'څښتن مینه کوي د خپل قوم سره او ساتنه کاندي د هغو خلکو چې دي د هغه نو مونږ ټیټېږو د هغه پښو ته او کوو یې د امرونو اطاعت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_3.mp3', '', 1761754199, 1761754199),
(53416, 'Deuteronomy 33:4', 'Deuteronomy', 33, 4, 'مونږ اطاعت کوو د هغه شریعت چې راکړی موسی چې ده قیمتي شتمني زمونږ د قوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_4.mp3', '', 1761754199, 1761754199),
(53417, 'Deuteronomy 33:5', 'Deuteronomy', 33, 5, 'کله چې راټول شول مشران او قبیلې د اسراییلو نو څښتن شولو پاچا د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_5.mp3', '', 1761754199, 1761754199),
(53418, 'Deuteronomy 33:6', 'Deuteronomy', 33, 6, 'موسی د روبین د قبیلې په اړه داسې وویل: روبین دې هېڅکله له منځه نه ځي که څه هم چې قبیله د دوی کوچنۍ ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_6.mp3', '', 1761754199, 1761754199),
(53419, 'Deuteronomy 33:7', 'Deuteronomy', 33, 7, 'هغه د یهودا د قبیلې په اړه داسې وویل: ای څښتنه! ته فریاد د هغوی واوره چې کوي یې د کومک دپاره بېرته یوځای کړه هغوی نورو قبیلو سره ته لاسونه کړه قوي د یهودا د دښمنانو مقابل کې د هغوی مرسته کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_7.mp3', '', 1761754199, 1761754199),
(53420, 'Deuteronomy 33:8', 'Deuteronomy', 33, 8, 'هغه د لاوي د قبیلې په اړه داسې وویل: ای څښتنه تا ورکړي دي اوریم او تمیم لاویانو ته یعنې خپل وفادارو خادمانو ته تا وازمایل په مسا کې هغوی او رښتیني دې ثابت کړل هغوی د مریبه د چینې څنګ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_8.mp3', '', 1761754199, 1761754199),
(53421, 'Deuteronomy 33:9', 'Deuteronomy', 33, 9, 'هغوی وښودله تاته وفا زیاته د مور او پلار، خویندو او ورونو اولادونو څخه ستا امرونو ته هغوی کېښوده غاړه او شول پاتې وفادار د ستا د لوظ سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_9.mp3', '', 1761754199, 1761754199),
(53422, 'Deuteronomy 33:10', 'Deuteronomy', 33, 10, 'هغوی ستا قوم ته زده کوي ستا د قانون اطاعت هغوی ږدي خوشبویي ستا په حضور کې او سوځېدونکې نذرانې ستا قربانګاه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_10.mp3', '', 1761754199, 1761754199),
(53423, 'Deuteronomy 33:11', 'Deuteronomy', 33, 11, 'مرسته وکړه د هغوی د قبیلې سره څښتنه چې قوي شي خوشحاله اوسه د هغوی د کارونو څخه له منځه یوسه ټول دښمنان د هغوی هغوی مه پرېږده چې بیا سر کړي راپورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_11.mp3', '', 1761754199, 1761754199),
(53424, 'Deuteronomy 33:12', 'Deuteronomy', 33, 12, 'هغه د بنیامین د قبیلې په اړه داسې وویل: دا ده هغه قبیله چې کړي مینه ورسره څښتن تعالی هغه اوسیږي د هغوی د غونډیو منځ کې او ټوله ورځ کوي ساتنه د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_12.mp3', '', 1761754199, 1761754199),
(53425, 'Deuteronomy 33:13', 'Deuteronomy', 33, 13, 'هغه د یوسف د اولادې په اړه داسې وویل: څښتن دې ووروي پرخه د هغوی په ځمکه او برکت دې واچوي د ځمکې لاندې اوبو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_13.mp3', '', 1761754199, 1761754199),
(53426, 'Deuteronomy 33:14', 'Deuteronomy', 33, 14, 'د هغوی ځمکه دې شي ډکه هغو مېوو نه چې پخې شوې وي په لمر باندې او شي دې غني د هر موسم په ډېرو ښو مېوو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_14.mp3', '', 1761754199, 1761754199),
(53427, 'Deuteronomy 33:15', 'Deuteronomy', 33, 15, 'پخوانۍ غونډۍ دې پټې د هغوی شي په ډېرو ښو مېوو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_15.mp3', '', 1761754199, 1761754199),
(53428, 'Deuteronomy 33:16', 'Deuteronomy', 33, 16, 'د هغوی ځمکه دې شي ډکه ټولو نعمتونو څخه هغه څښتن دې د هغوی سره نېکي وکړي چې شو ښکاره په سوځېدونکي بوټي کې دا برکتونه دې نازل شي د یوسف په اولادې باندې ځکه رهبر ؤ هغه د خپلو ورونو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_16.mp3', '', 1761754199, 1761754199),
(53429, 'Deuteronomy 33:17', 'Deuteronomy', 33, 17, 'په قوت کې دی یوسف لکه غویي په شان د وحشي غویي د ښکرو په شان د هغه ښکرونه دي د منسي زرګونه خلک او د افرایم دي لس ګونه زره خلک نور قومونه وهي هغو ښکرونو باندې او ټېل وهي هغوی د دنیا اخري سرته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_17.mp3', '', 1761754199, 1761754199),
(53430, 'Deuteronomy 33:18', 'Deuteronomy', 33, 18, 'هغه د زبولون او یساکار د قبیلو په اړه داسې وویل: زبولون دې وي خوشحاله تجارت کې په بحیرې باندې او خپل وطن کې دې شي ډېر د یساکار دولت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_18.mp3', '', 1761754199, 1761754199),
(53431, 'Deuteronomy 33:19', 'Deuteronomy', 33, 19, 'هغوی رابولي نورې قبیلې خپل غره ته او وړاندې کوي هلته سمه قربانۍ لاسته راوړي هغوی خپل دولت له بحیرو څخه او د بحیرې د غاړې شګو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_19.mp3', '', 1761754199, 1761754199),
(53432, 'Deuteronomy 33:20', 'Deuteronomy', 33, 20, 'هغه د جاد د قبیلې په اړه داسې وویل: ودې شي ستاینه د خدای چې یې پراخه د هغوی سیمه کړه لکه زمري په شان جاد وباسي انتظار چې مټه یا کوپړۍ کړي غوڅه د ښکار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_20.mp3', '', 1761754199, 1761754199),
(53433, 'Deuteronomy 33:21', 'Deuteronomy', 33, 21, 'هغوی د ځان دپاره واخیستله ښه ښه ځمکه د یو مشر برخه ورکړل شوه هغوی ته کله راټول چې شول مشران د اسراییلو کېښوده غاړه د جاد خلکو قوانینو او حکمونو د څښتن ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_21.mp3', '', 1761754199, 1761754199),
(53434, 'Deuteronomy 33:22', 'Deuteronomy', 33, 22, 'هغه د دان د قبیلې په اړه داسې وویل: دان د زمري بچی دی چې په باشان کې د خپل غاره څخه وهي ټوپونه خپل دښمن پسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_22.mp3', '', 1761754199, 1761754199),
(53435, 'Deuteronomy 33:23', 'Deuteronomy', 33, 23, 'هغه د نفتالي د قبیلې په اړه داسې وویل: ډېر برکت دی نفتالي سره د څښتن د نېکۍ د هغوی ځمکه رسي د جلیل له بحیرې نه تر جنوبه پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_23.mp3', '', 1761754199, 1761754199),
(53436, 'Deuteronomy 33:24', 'Deuteronomy', 33, 24, 'هغه د اشیر د قبیلې په اړه داسې وویل: نسبت نورو قبیلو ته ډېر برکت دی د اشیر د قبیلې سره هغه دې غوره اوسي د خپلو ورونو منځ کې او د هغه ځمکه دې وي ډکه د زیتون له تېلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_24.mp3', '', 1761754199, 1761754199),
(53437, 'Deuteronomy 33:25', 'Deuteronomy', 33, 25, 'په هغو دروازو دې وشي ساتنه د هغه د ښارونو چې اړمونه وي د اوسپنې او برنجو په کې او ژوند دې کوي هغه همېشه امن کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_25.mp3', '', 1761754199, 1761754199),
(53438, 'Deuteronomy 33:26', 'Deuteronomy', 33, 26, 'ای د اسراییلو خلکو! هېڅ یو خدای نه دی زمونږ د خدای په شان هغه سپریږي د اسمان په ورېځو د خپل شوکت او شانه سره چې راشي تاسو ته کومک دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_26.mp3', '', 1761754199, 1761754199),
(53439, 'Deuteronomy 33:27', 'Deuteronomy', 33, 27, 'ابدي خدای زمونږ د پټېدلو ځای دی هغه نیسي مونږه په ابدي غېږه کې خدای کړل لېرې دښمنان ستاسو ستاسو له مخې څخه او درته ویې ویل چې تباه کړئ هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_27.mp3', '', 1761754199, 1761754199),
(53440, 'Deuteronomy 33:28', 'Deuteronomy', 33, 28, 'نو اولاده د یعقوب کوي په سوله کې ژوند دي په امن هغوی په داسې خاوره کې چې ده ډکه د غلو او د شرابو څخه او چېرته چې پرخه له اسمانه څخه ورکوي اوبه ځمکې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_28.mp3', '', 1761754199, 1761754199),
(53441, 'Deuteronomy 33:29', 'Deuteronomy', 33, 29, 'اسراییلو! تاسو څومره بختور یئ چې هېڅوک نشته لکه ستاسو په شان یو داسې قوم چې څښتن ژغورلی د دې دپاره چې دفاع وکړي ستاسو څخه او بری درکاندي څښتن په خپله ستاسو سپر او ستاسو توره ده رحم دپاره به راځي دښمنان ستاسو او زاري به کوي او تاسو تر پښو لاندې کوئ به هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy33_verse_29.mp3', '', 1761754199, 1761754199),
(53442, 'Jeremiah 26:1', 'Jeremiah', 26, 1, 'دلته يرمياه ته د مالِک خُدائ پېغام د يهويقيم د يوسياه د زوئ د يهوداه بادشاه د حکومت په وړومبنى سر کښې ورکړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_1.mp3', '', 1761754199, 1761754199),
(53443, 'Jeremiah 26:2', 'Jeremiah', 26, 2, 'مالِک خُدائ هغۀ ته داسې وفرمائيل چې، ”لاړ شه او د مالِک خُدائ د کور په دربار کښې ودرېږه، او هغه خلقو ته اعلان وکړه څوک چې د يهوداه د خوا او شا ښارونو نه د عبادت دپاره راغلى دى. هغوئ ته زما کلام پوره پوره واوروه او يو لفظ هم ترې نه کم نۀ کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_2.mp3', '', 1761754199, 1761754199),
(53444, 'Jeremiah 26:3', 'Jeremiah', 26, 3, 'کېدے شى چې هغوئ تا ته غوږ ونيسى او هر يو د خپلو بدو لارو نه راواوړى. کومه منصوبه چې ما د هغوئ خلاف جوړه کړې وه، نو بيا به زۀ خپل سوچ بدل کړم او هغه افت به پرې نۀ راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_3.mp3', '', 1761754199, 1761754199),
(53445, 'Jeremiah 26:4', 'Jeremiah', 26, 4, 'هغوئ ته ووايه، مالِک خُدائ فرمائى، کۀ چرې تاسو ما ته غوږ ونۀ نيسئ او کوم شريعت چې ما تاسو ته پېش کړے دے د هغې پيروى ونۀ کړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_4.mp3', '', 1761754199, 1761754199),
(53446, 'Jeremiah 26:5', 'Jeremiah', 26, 5, 'او کۀ چرې تاسو زما د خِدمت کوونکو پېغمبرانو کلام ته غوږ ونۀ نيسئ کوم چې ما تاسو ته بار بار درلېږلى دى خو تاسو هغوئ ته غوږ ونۀ نيولو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_5.mp3', '', 1761754199, 1761754199),
(53447, 'Jeremiah 26:6', 'Jeremiah', 26, 6, 'نو زۀ به د دې کور سره هم هغه شان کار وکړم لکه څنګه مې چې د سيلا سره کړے وو، او د زمکې په مخ به د دُنيا ټول قومونه د دې ښار نوم په لعنت کولو سره اخلى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_6.mp3', '', 1761754199, 1761754199),
(53448, 'Jeremiah 26:7', 'Jeremiah', 26, 7, 'کله چې يرمياه د مالِک خُدائ په کور کښې دا کلام واورولو نو اِمامانو، پېغمبرانو او ټولو خلقو د هغۀ کلام واورېدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_7.mp3', '', 1761754199, 1761754199),
(53449, 'Jeremiah 26:8', 'Jeremiah', 26, 8, 'نو چې څنګه يرمياه هغه کلام خلقو ته اورول ختم کړو کوم چې ورته مالِک خُدائ حکم کړے وو چې دې خلقو ته يې واوروى نو سمدستى اِمامانو، نبيانو او ټولو خلقو هغه ونيولو او چغې يې کړې، ”دا ضرورى ده چې تۀ د دې په وجه مړ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_8.mp3', '', 1761754199, 1761754199),
(53450, 'Jeremiah 26:9', 'Jeremiah', 26, 9, 'تۀ ولې د مالِک خُدائ په کور کښې د هغۀ په نوم پېغام ورکوې چې دا کور به لکه د سيلا په شان شى او دا ښار به په صحرا او کنډرو بدل شى؟“ نو د مالِک خُدائ په کور کښې ټول خلق د يرمياه نه راتاو شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_9.mp3', '', 1761754199, 1761754199),
(53451, 'Jeremiah 26:10', 'Jeremiah', 26, 10, 'کله چې د يهوداه آفسرانو د دې خبرو په حقله واورېدل، هغوئ د شاهى محل نه د مالِک خُدائ د کور طرف ته لاړل او هلته د نوې دروازې په نوم دروازه کښې په داخلېدو سره په خپلو ځايونو باندې کښېناستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_10.mp3', '', 1761754199, 1761754199),
(53452, 'Jeremiah 26:11', 'Jeremiah', 26, 11, 'نو بيا اِمامانو او پېغمبرانو، ټولو آفسرانو او نورو خلقو ته وفرمائيل چې، ”دې سړى ته دې د مرګ سزا ورکړے شى ځکه چې هغۀ د دې ښار خِلاف پېشګوئې وکړه او تاسو په خپلو غوږُونو واورېده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_11.mp3', '', 1761754199, 1761754199),
(53453, 'Jeremiah 26:12', 'Jeremiah', 26, 12, 'نو بيا يرمياه ټولو آفسرانو او ټولو خلقو ته وفرمائيل، ”زۀ مالِک خُدائ رالېږلے يم چې د دې کور او د دې ښار خِلاف هغه ټولې پېشګويانې وکړم کومې چې تاسو واورېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_12.mp3', '', 1761754199, 1761754199),
(53454, 'Jeremiah 26:13', 'Jeremiah', 26, 13, 'تاسو اوس د خپلو طريقو او اعمالو اصلاح وکړئ او د مالِک خُدائ ستاسو د خُدائ پاک تابعدارى وکړئ. نو بيا به مالِک خُدائ خپل سوچ بدل کړى او د کوم افت د نازلېدو منصوبه يې چې جوړه کړې ده هغه به نۀ نازلوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_13.mp3', '', 1761754199, 1761754199),
(53455, 'Jeremiah 26:14', 'Jeremiah', 26, 14, 'ترڅو پورې چې زما خبره ده، زۀ خو ستاسو په قبضه کښې يم، څۀ چې تاسو ته ښۀ او صحيح ښکارى هم هغه ما سره وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_14.mp3', '', 1761754199, 1761754199),
(53456, 'Jeremiah 26:15', 'Jeremiah', 26, 15, 'خو تاسو په دې يقين وساتئ، کۀ چرې تاسو ما مړ کړئ، نو تاسو او د دې ښار خلق څوک چې په کښې اوسيږى د يو بې‌ګناه کس خون به په خپله غاړه واخلئ ځکه چې په حقيقت کښې زۀ مالِک خُدائ تاسو ته رالېږلے يم، چې دا ټولې خبرې ستاسو غوږونو ته درورسوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_15.mp3', '', 1761754199, 1761754199),
(53457, 'Jeremiah 26:16', 'Jeremiah', 26, 16, 'نو آفسرانو او خلقو چې دا واورېدل، نو اِمامانو او پېغمبرانو ته يې ووئيل، ”دې سړى ته دې د مرګ سزا ورنۀ کړے شى، ځکه چې هغۀ مونږ ته د مالِک خُدائ زمونږ د خُدائ پاک په نوم خبرې وکړې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_16.mp3', '', 1761754199, 1761754199),
(53458, 'Jeremiah 26:17', 'Jeremiah', 26, 17, 'نو بيا د قوم يو څو مشران راپاڅېدل او ټولو حاضرو خلقو ته يې ووئيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_17.mp3', '', 1761754199, 1761754199),
(53459, 'Jeremiah 26:18', 'Jeremiah', 26, 18, '”د مورشيت ميکاه نبى چې د حزقياه د بادشاهت په ورځو کښې د يهوداه بادشاه وو، پېشګوئې وکړه. هغۀ د يهوداه ټولو خلقو ته وفرمائيل، دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، صيون به لکه د پټې په شان په يوې واړولے‎ شى، د يروشلم نه به د خاورو ډېرے جوړ شى، او په اوچتو غونډو چرته چې د خُدائ کور دے په هغې کښې به جاړې بوټى راشنۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_18.mp3', '', 1761754199, 1761754199),
(53460, 'Jeremiah 26:19', 'Jeremiah', 26, 19, 'ولې حزقياه چې د يهوداه بادشاه وو هغه په مرګ محکوم کړو څۀ؟ آيا حزقياه د مالِک خُدائ نه ونۀ يرېدو چې د هغۀ رحم ولټوى؟ آيا مالِک خُدائ خپله فېصله بدله نۀ کړه د کوم افت د رانازلېدو چې هغۀ د دوئ خلاف منصوبه جوړه کړې وه؟ مونږ په خپله په خپل ځان د سخت افت راوستو په حالت کښې يُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_19.mp3', '', 1761754199, 1761754199),
(53461, 'Jeremiah 26:20', 'Jeremiah', 26, 20, 'په هغه ورځو کښې يو بل نبى د اورِياه په نوم چې د قِريَت‌يعريم اوسېدونکے وو او د سمعياه زوئ وو د يرمياه نبى په شان د مالِک خُدائ په نوم نبوت کولو. هغۀ هم د دې ښار او د دې خلقو خلاف لکه څنګه چې يرمياه خبرې کړې وې يو شان خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_20.mp3', '', 1761754199, 1761754199),
(53462, 'Jeremiah 26:21', 'Jeremiah', 26, 21, 'کله چې يهويقيم بادشاه، او د هغۀ ټولو فوجيانو او آفسرانو د اورِياه خبرې واورېدلې، نو بادشاه د هغۀ د قتلولو کوشش وکړو. خو کله چې اورِياه واورېدل نو د يرې نه مِصر ته وتښتېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_21.mp3', '', 1761754199, 1761754199),
(53463, 'Jeremiah 26:22', 'Jeremiah', 26, 22, 'نو بيا يهويقيم بادشاه الناتن د عکبور زوئ مِصر ته سره د نورو کسانو ولېږلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_22.mp3', '', 1761754199, 1761754199),
(53464, 'Jeremiah 26:23', 'Jeremiah', 26, 23, 'نو هغوئ اورِياه په مِصر کښې ونيولو او يهويقيم بادشاه له يې راوستلو، او هغه يې په تُوره قتل کړو او د هغۀ لاش يې د عامو خلقو په قبرستان کښې ښخ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_23.mp3', '', 1761754199, 1761754199),
(53465, 'Jeremiah 26:24', 'Jeremiah', 26, 24, 'خو اخيقام د سافن زوئ د يرمياه مدد کولو، نو ځکه هغه د مرګ دپاره خلقو ته حواله نۀ کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah26_verse_24.mp3', '', 1761754199, 1761754199),
(53466, 'Joshua 10:1', 'Joshua', 10, 1, 'د اورشلیم پاچا ادوني صدق واورېدل چې یوشع عای نیولی دی او هغه یې بیخي له منځه وړی او د هغه ځای پاچا یې وژلی دی لکه څنګه چې هغه د اریحا او د هغه ځای د پاچا سره همداسې کړي وو. هغه دا هم واورېدل چې د جبعون خلکو د اسراییلو سره د سولې تړون کړی دی او د هغوی په منځ کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_1.mp3', '', 1761754199, 1761754199),
(53467, 'Joshua 10:2', 'Joshua', 10, 2, 'د اورشلیم خلک ډېر وېرېدل، ځکه چې جبعون د شاهي ښارونو په شان یو ډېر لوی ښار ؤ. دا ښار د عای څخه لوی ؤ او ټول خلک یې ښه جنګیالي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_2.mp3', '', 1761754199, 1761754199),
(53468, 'Joshua 10:3', 'Joshua', 10, 3, 'نو ادوني صدق د حبرون پاچا هوهام، د یرموت پاچا فرآم، د لاخیش پاچا یافیع او د عجلون پاچا دبیر ته دا لاندېنی پیغام ولېږه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_3.mp3', '', 1761754199, 1761754199),
(53469, 'Joshua 10:4', 'Joshua', 10, 4, '«راشئ او زما سره مرسته وکړئ چې په جبعون باندې حمله وکړو، ځکه چې د هغه ځای خلکو د یوشع او اسراییلیانو سره د سولې تړون کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_4.mp3', '', 1761754199, 1761754199),
(53470, 'Joshua 10:5', 'Joshua', 10, 5, 'د اموریانو دغو پنځو پاچاهانو یعنې د اورشلیم پاچا، د حبرون پاچا، د یرموت پاچا، د لاخیش پاچا او د عجلون پاچا خپل ځواکونه سره یوځای کړل. هغوی جبعون کلابند کړ او په هغه باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_5.mp3', '', 1761754199, 1761754199),
(53471, 'Joshua 10:6', 'Joshua', 10, 6, 'جبعونیانو یوشع ته هغه کمپ ته چې په جلجال کې ؤ دا پیغام ولېږه: «د خپلو خدمتګارانو څخه لاس مه اخله. همدا اوس راشه او زمونږ سره مرسته وکړه او مونږ وژغوره! ځکه چې د غرنۍ سیمې د اموریانو ټولو پاچاهانو زمونږ په ضد ځواکونه سره یوځای کړي دي او په مونږ باندې یې حمله کړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_6.mp3', '', 1761754199, 1761754199),
(53472, 'Joshua 10:7', 'Joshua', 10, 7, 'نو یوشع د خپل ټول لښکر سره چې د هغه تر ټولو ښه جنګیالي په کې شامل وو د جلجال څخه روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_7.mp3', '', 1761754199, 1761754199),
(53473, 'Joshua 10:8', 'Joshua', 10, 8, 'څښتن یوشع ته وویل: «د هغوی څخه مه وېرېږه. هغوی به تاته په لاس درکړم. د هغوی څخه به یو تن هم ونه شي کولای چې ستا په وړاندې ودریږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_8.mp3', '', 1761754199, 1761754199),
(53474, 'Joshua 10:9', 'Joshua', 10, 9, 'یوشع او د هغه لښکر ټوله شپه د جلجال څخه د جبعون پورې مزل وکړ او په اموریانو باندې یې ناڅاپي حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_9.mp3', '', 1761754199, 1761754199),
(53475, 'Joshua 10:10', 'Joshua', 10, 10, 'څښتن اموریان د اسراییلیانو په لیدلو سره ووېرول. اسراییلیانو هغوی په جبعون کې ووژل او پاتې یې په بیت حورون کې د غره د غاښي په ښکتنۍ لاره تعقیب کړل. هغوی تر هغه وخته پورې په اموریانو باندې خپلې حملې ته دوام ورکړ، ترڅو د عزیقه او مقیده ښارونو ته ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_10.mp3', '', 1761754199, 1761754199),
(53476, 'Joshua 10:11', 'Joshua', 10, 11, 'کله چې اموریان د اسراییلو د لښکرو څخه ښکته د غاښي په لاره باندې تښتېدل، څښتن په هغوی باندې تر عزیقه پورې غټې غټې ږلۍ واورولې. د هغو خلکو شمېر چې په ږلیو مړه شول د هغو خلکو څخه زیات وو چې د اسراییلیانو له خوا ووژل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_11.mp3', '', 1761754199, 1761754199),
(53477, 'Joshua 10:12', 'Joshua', 10, 12, 'په هغه ورځ چې څښتن اسراییلیانو ته په اموریانو باندې بری ورکړ، یوشع څښتن ته دعا وکړه. هغه د اسراییلیانو په مخکې وویل: ای لمره، ودرېږه د جبعون په سر باندې ای سپوږمۍ، ودرېږه د ایالون په دره باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_12.mp3', '', 1761754199, 1761754199),
(53478, 'Joshua 10:13', 'Joshua', 10, 13, 'نو لمر او سپوږمۍ تر هغه وخته پورې ودرېدل، ترڅو چې قوم په خپلو دښمنانو باندې بری وموند. دا پېښه د یاشر په کتاب کې لیکل شوې ده. لمر د اسمان په منځ کې ودرېده او ټوله ورځ ونه لوېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_13.mp3', '', 1761754199, 1761754199),
(53479, 'Joshua 10:14', 'Joshua', 10, 14, 'داسې ورځ هېڅکله نه ده راغلې او نه به راشي چې خدای لمر او سپوږمۍ د یو انسان د دعا په خاطر ودروي. څښتن په رښتیا سره د اسراییلو په خاطر جنګېده!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_14.mp3', '', 1761754199, 1761754199),
(53480, 'Joshua 10:15', 'Joshua', 10, 15, 'د جګړې څخه وروسته یوشع او د هغه لښکر بېرته خپل کمپ ته جلجال ته ستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_15.mp3', '', 1761754199, 1761754199),
(53481, 'Joshua 10:16', 'Joshua', 10, 16, 'د جګړې په وخت کې هغه پنځه اموریایي پاچاهان تښتېدلي وو او ځانونه یې په مقیده کې په سمڅه کې پټ کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_16.mp3', '', 1761754199, 1761754199),
(53482, 'Joshua 10:17', 'Joshua', 10, 17, 'یو چا هغوی پیدا کړل او یوشع خبر شو چې هغوی د مقیدې په سمڅه کې پټ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_17.mp3', '', 1761754199, 1761754199),
(53483, 'Joshua 10:18', 'Joshua', 10, 18, 'یوشع خپلو کسانو ته وویل: «د سمڅې خولې ته یو څو غټې تیږې ورغړوئ او هلته یو څو ساتونکي ودروئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_18.mp3', '', 1761754199, 1761754199),
(53484, 'Joshua 10:19', 'Joshua', 10, 19, 'خو تاسو په خپله هلته مه پاتې کېږئ. د دښمن پسې شئ او د شا له خوا ورباندې حمله وکړئ. هغوی مه پرېږدئ چې خپلو ښارونو ته ورورسیږي! ځکه چې زمونږ څښتن خدای مونږ په هغوی باندې بریالي کړي یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_19.mp3', '', 1761754199, 1761754199),
(53485, 'Joshua 10:20', 'Joshua', 10, 20, 'نو یوشع او اسراییلیانو د دښمن عسکر نژدې ټول له منځه یووړل. خو یوازې یو څو کسان چې پاتې شوي وو هغوی خپلو دېوال لرونکو ښارونو ته ورورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_20.mp3', '', 1761754199, 1761754199),
(53486, 'Joshua 10:21', 'Joshua', 10, 21, 'بیا ټول لښکر یوشع ته هغه کمپ ته چې په مقیده کې ؤ روغ راستون شو. له دې وروسته هېچا جرات نه شو کولای چې د اسراییلیانو په هکله کومه بده خبره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_21.mp3', '', 1761754199, 1761754199),
(53487, 'Joshua 10:22', 'Joshua', 10, 22, 'بیا یوشع وویل: «د سمڅې خوله خلاصه کړئ او هغه پنځه پاچاهان ماته راوباسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_22.mp3', '', 1761754199, 1761754199),
(53488, 'Joshua 10:23', 'Joshua', 10, 23, 'نو هغوی هغه پنځه پاچاهان یعنې د اورشلیم، حبرون، یرموت، لاخیش او د عجلون پاچاهان د سمڅې څخه راوویستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_23.mp3', '', 1761754199, 1761754199),
(53489, 'Joshua 10:24', 'Joshua', 10, 24, 'کله چې هغوی دا پاچاهان یوشع ته راوستل، هغه د اسراییلو ټول خلک راوغوښتل او د لښکرو قوماندانانو ته یې چې د هغه سره راغلي وو امر وکړ چې راشي او د دې پاچاهانو په ورمېږونو باندې خپلې پښې کېږدي. نو هغوی همداسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_24.mp3', '', 1761754199, 1761754199),
(53490, 'Joshua 10:25', 'Joshua', 10, 25, 'بیا یوشع خپلو قوماندانانو ته وویل: «مه وېرېږئ او زړونه مه بایلئ. قوي او زړور اوسئ، ځکه چې څښتن به ستاسو په ټولو دښمنانو باندې چې تاسو ورسره جنګ کوئ، همداسې کار وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_25.mp3', '', 1761754199, 1761754199),
(53491, 'Joshua 10:26', 'Joshua', 10, 26, 'بیا یوشع هغه پنځه پاچاهان ووژل او هغوی یې په پنځو ونو کې ځوړند کړل او د هغوی مړي تر ماښامه پورې هلته پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_26.mp3', '', 1761754199, 1761754199),
(53492, 'Joshua 10:27', 'Joshua', 10, 27, 'د لمرپرېواته په وخت کې یوشع امر وکړ او هغوی د هغو پاچاهانو مړي د ونو څخه راښکته کړل او په هغه سمڅه کې یې وغورځول چې هغوی مخکې په کې پټ شوي وو. هغوی د سمڅې په خوله کې لویې لویې تیږې کېښودلې او هغه تر نن ورځې پورې هلته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_27.mp3', '', 1761754199, 1761754199),
(53493, 'Joshua 10:28', 'Joshua', 10, 28, 'په هماغه ورځ یوشع د مقیده په ښار باندې حمله وکړه او هغه یې ونیوه او د هغه پاچا یې وواژه. هغه د دې ښار ټول خلک ووژل. هېڅوک یې ژوندی پرېنښود. هغه د مقیده د پاچا سره هماغه شان چلند وکړ لکه څنګه چې هغه د اریحا د پاچا سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_28.mp3', '', 1761754199, 1761754199),
(53494, 'Joshua 10:29', 'Joshua', 10, 29, 'وروسته له هغې یوشع او د هغه ټول لښکر له مقیده څخه لبنه ته لاړل او په هغه ځای باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_29.mp3', '', 1761754199, 1761754199),
(53495, 'Joshua 10:30', 'Joshua', 10, 30, 'څښتن اسراییلیان په دې ښار او د هغه په پاچا باندې هم بریالي کړل. هغوی هېڅوک ژوندی پرېنښود او د ښار ټول خلک یې ووژل. لکه څنګه چې هغوی د اریحا پاچا وژلی ؤ هماغه شان هغوی د لبنه پاچا هم وواژه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_30.mp3', '', 1761754199, 1761754199),
(53496, 'Joshua 10:31', 'Joshua', 10, 31, 'له هغې وروسته یوشع او د هغه لښکر د لبنه څخه لاخیش ته لاړل، هغه یې کلابند کړ او حمله یې ورباندې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_31.mp3', '', 1761754199, 1761754199),
(53497, 'Joshua 10:32', 'Joshua', 10, 32, 'د جګړې په دوهمه ورځ څښتن اسراییلیان په لاخیش باندې بریالي کړل. هغوی د ښار ټول خلک د لبنه د خلکو په شان ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_32.mp3', '', 1761754199, 1761754199),
(53498, 'Joshua 10:33', 'Joshua', 10, 33, 'هورام د جازر پاچا د لاخیش سره د مرستې دپاره راغی، خو یوشع هغه او د هغه لښکر ته ماتې ورکړه او د هغوی یو کس یې هم ژوندی پرېنښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_33.mp3', '', 1761754199, 1761754199),
(53499, 'Joshua 10:34', 'Joshua', 10, 34, 'بیا یوشع او د هغه لښکر د لاخیش څخه عجلون ته لاړل، هغه یې کلابند کړ او حمله یې ورباندې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_34.mp3', '', 1761754199, 1761754199),
(53500, 'Joshua 10:35', 'Joshua', 10, 35, 'هغوی په هماغه ورځ دا ښار ونیوه او د لاخیش په شان یې د هغه ځای ټول خلک ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_35.mp3', '', 1761754199, 1761754199),
(53501, 'Joshua 10:36', 'Joshua', 10, 36, 'له هغې وروسته هغوی د عجلون څخه د غونډیو له لارې حبرون ته وروختل او په هغه باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_36.mp3', '', 1761754199, 1761754199),
(53502, 'Joshua 10:37', 'Joshua', 10, 37, 'هغوی هغه ښار او د هغه شاوخوا کلي ونیول، بیا یې ټول خلک ووژل چې په هغو کې پاچا هم شامل ؤ. لکه څنګه چې هغوی عجلون له منځه وړی ؤ هماغه شان یې حبرون هم بیخي له منځه یووړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_37.mp3', '', 1761754199, 1761754199),
(53503, 'Joshua 10:38', 'Joshua', 10, 38, 'بیا یوشع د خپل لښکر سره راوګرځېد او په دبیر باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_38.mp3', '', 1761754199, 1761754199),
(53504, 'Joshua 10:39', 'Joshua', 10, 39, 'هغوی ښار، د هغه پاچا او شاوخوا ټول کلي ونیول. د هغه ځای ټول خلک یې بیخي له منځه یووړل. هغوی د دبیر او د هغه ځای د پاچا سره هماغه شان کار وکړ لکه څنګه یې چې د حبرون د ښار او د لبنه د ښار او پاچا سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_39.mp3', '', 1761754199, 1761754199),
(53505, 'Joshua 10:40', 'Joshua', 10, 40, 'یوشع ټوله خاوره فتح کړه. هغه د غرنۍ سیمې، د غرونو د ختیځو لمنو، د غرونو د لوېدیځو لمنو او د کنعان د جنوبي سیمې پاچاهانو ته ماتې ورکړه. هغه هېڅوک ژوندی پرېنښود، ټول ووژل شول. دا هغه څه وو چې د اسراییلو څښتن خدای د هغو حکم کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_40.mp3', '', 1761754199, 1761754199),
(53506, 'Joshua 10:41', 'Joshua', 10, 41, 'یوشع دا خاوره د قادش برنیع څخه تر غزې او د جوشن د ټولې سیمې څخه تر جبعون پورې فتح کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_41.mp3', '', 1761754199, 1761754199),
(53507, 'Joshua 10:42', 'Joshua', 10, 42, 'یوشع په یوې لښکر کشۍ سره په دې ټولو پاچاهانو او د هغوی په سیمو باندې فتح تر لاسه کړه، ځکه چې د اسراییلو څښتن خدای د اسراییلو دپاره جګړه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_42.mp3', '', 1761754199, 1761754199),
(53508, 'Joshua 10:43', 'Joshua', 10, 43, 'بیا یوشع د خپل لښکر سره په جلجال کې خپل کمپ ته راستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua10_verse_43.mp3', '', 1761754199, 1761754199),
(53509, 'Psalms 73:1', 'Psalms', 73, 1, 'په رښتیا چې خدای ښه دی اسراییلو سره د هغه چا سره چې زړونه یې پاک دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_1.mp3', '', 1761754199, 1761754199),
(53510, 'Psalms 73:2', 'Psalms', 73, 2, 'خو زما په هکله دا چې نژدې ؤ چې رانه ورک وای د پښو د ایښودلو ځای او زما پښې وای ښوېدلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_2.mp3', '', 1761754199, 1761754199);